update public.global_settings set landing_content = jsonb_set(coalesce(landing_content, '{}'::jsonb), '{features,items}', '[{"icon":"Globe","title":"নিজের ব্র্যান্ডেড স্টোর","desc":"কাস্টম ডোমেইন, লোগো, কালার, থিম — কাস্টমার শুধু আপনাকে দেখবে।"},{"icon":"Wallet","title":"পেমেন্ট সবচেয়ে সহজ","desc":"bKash, Nagad, Rocket, SSLCommerz, EPS — COD + অনলাইন।"},{"icon":"Megaphone","title":"Ads ট্র্যাকিং অটো","desc":"Facebook Pixel/CAPI + TikTok Events API — কোন অ্যাডে কত সেল।"}]'::jsonb) where id = 1;